		const { store } = open();
		const now = new Date("2026-11-11T10:30:00.000Z");
		store.recordBump("shelf", { bumpedAt: "2026-11-07T10:52:55.000Z", bumpCount: 3 });
		const days = { ...card, bumpAgoMinutes: null, bumpAgoDays: 5, bumpCount: 3 };
		store.replaceFromPhone([days], now);
		const shelf = store.listings().find((listing) => listing.id === "shelf");
		expect(shelf?.bumpedAt).toBe("2026-11-06T10:30:00.000Z");
		expect(Date.parse(shelf?.nextBumpAt ?? "")).toBeLessThan(now.getTime());
	});

	test("하루 단위 문구와 맞는 아는 끌올 시각은 그대로 쓴다", () => {
		const { store } = open();
		const now = new Date("2026-11-11T10:30:00.000Z");
		store.recordBump("shelf", { bumpedAt: "2026-11-06T02:00:00.000Z", bumpCount: 3 });
		store.replaceFromPhone([{ ...card, bumpAgoMinutes: null, bumpAgoDays: 5, bumpCount: 3 }], now);
		expect(store.listings().find((listing) => listing.id === "shelf")?.bumpedAt).toBe("2026-11-06T02:00:00.000Z");
	});

	test("관측값보다 늦은 추정이 나오면 추정으로 다시 긋는다", () => {
		const { store } = open();
		const observed = new Date(Date.now() + 3_600_000).toISOString();
		store.recordCooldown("shelf", observed);
