/**
 * 판매중 글·규칙·실행 목록. 실행은 승인 없이 `currentBatch`로 만들고,
 * 옛 승인·취소 경로도 남겨 둔다. 폰 파일은 PhoneFiles가 맡는다.
 */
import { DatabaseSync } from "node:sqlite";
import {
	batchSignature,
	DEFAULT_SETTINGS,
	itemsFromProposals,
	type BatchFile,
	type LastRun,
	type ScreenListing,
	type ScreenSettings,
} from "./batch";
