if (!names.has("next_bump_at")) this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_at TEXT");
if (!names.has("next_bump_observed"))
	this.db.exec("ALTER TABLE listing ADD COLUMN next_bump_observed INTEGER NOT NULL DEFAULT 0");

/** 폰이 보여 준 다음 끌올 시각만. 우리 추정은 여기 넣지 않는다. */
private observedNextBumps(): Map<string, string> {
	const rows = this.db
		.prepare(`SELECT id, next_bump_at FROM listing WHERE next_bump_observed = 1 AND next_bump_at IS NOT NULL`)
		.all() as { id: string; next_bump_at: string }[];
	return new Map(rows.map((row) => [row.id, row.next_bump_at]));
}

/** 실행이 끌올 하나를 마쳤을 때. 횟수를 안 주면 지금 값 + 1, 다음 시각을 안 주면 추정표를 쓴다. */
recordBump(
	listingId: string,
	bump: { bumpedAt: string; bumpCount?: number | null; nextBumpAt?: string | null },
): void {
	const row = this.listings().find((listing) => listing.id === listingId);
	if (!row) return;
	const bumpCount = bump.bumpCount ?? (row.bumpCount ?? 0) + 1;
	const observed = bump.nextBumpAt ?? null;
	const next = observed ?? estimateNextBumpAt(bump.bumpedAt, bumpCount);
	this.db
		.prepare(
			`UPDATE listing SET bumped_at = :bumped_at, bump_count = :bump_count, next_bump_at = :next_bump_at,
			 next_bump_observed = :next_bump_observed
			 WHERE id = :id`,
		)
		.run({
			":id": listingId,
			":bumped_at": bump.bumpedAt,
			":bump_count": bumpCount,
			":next_bump_at": next,
			":next_bump_observed": observed !== null ? 1 : 0,
		});
}

/** 폰에 뜬 남은 시간을 그대로 남긴다. 관측값은 추정을 이긴다. */
recordCooldown(listingId: string, next: string): void {
	this.db.prepare(`UPDATE listing SET next_bump_at = :next, next_bump_observed = 1 WHERE id = :id`).run({
		":id": listingId,
		":next": next,
	});
}

