edits.newText:
/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	if (card.bumpAgoMinutes !== null && card.bumpAgoMinutes !== undefined && Number.isFinite(card.bumpAgoMinutes)) {
		return new Date(now - card.bumpAgoMinutes * 60_000).toISOString();
	}
	if (card.bumpAgoDays === null || card.bumpAgoDays === undefined) return prior;
	// 하루 단위 문구는 시각을 알려 주지 않는다. 아는 시각이 그 날짜와 맞으면 그대로 지킨다.
	const known = prior === null ? Number.NaN : Date.parse(prior);
	if (Number.isFinite(known) && Math.round((now - known) / 86_400_000) === card.bumpAgoDays) return prior;
	return new Date(now - card.bumpAgoDays * 86_400_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다. 우리가 어림한 지난 값은 지키지 않는다.
 */
function ingestedNextBumpAt(input: {
	observedNext: string | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	return laterOf(input.observedNext, estimate);
}

